<div class="span-2 delivery-selector"><h3>Where in Lebanon should we deliver?</h3><div class="form-grid"><label>Search delivery areas<input type="search" data-delivery-search placeholder="Area, town or district" autocomplete="off"></label><label>Filter by governorate<select data-delivery-governorate><option value="">All governorates</option><?php foreach(array_unique(array_column($options,'governorate')) as $g): ?><option><?= e($g) ?></option><?php endforeach ?></select></label></div>
